#define freq(f) texture(iChannel0, vec2(f, 0.25)).x * 0.8

float avgFreq(float start, float end, float step) {
    float div = 0.0;
    float total = 0.0;
    for (float pos = start; pos < end; pos += step) {
        div += 1.0;
        total += freq(pos);
    }
    return total / div;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates
    vec2 uv = fragCoord.xy / iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    // Frequency bands
    float bassFreq = pow(avgFreq(0.0, 0.1, 0.01), 0.85); // Bass
    float medFreq = pow(avgFreq(0.1, 0.6, 0.01), 0.85);  // Mid
    float topFreq = pow(avgFreq(0.6, 1.0, 0.01), 0.85);  // Treble

    // Background
    vec3 color = vec3(0.1, 0.1, 0.1); // Dark background

    // Afro (reacts to bass)
    vec2 afroCenter = vec2(0.0, 0.2);
    float afroRadius = 0.4 + bassFreq * 0.2 * sin(iTime * 2.0);
    float afro = length(uv - afroCenter) - afroRadius;
    color = mix(color, vec3(0.0, 0.0, 0.0), smoothstep(0.02, 0.0, afro));

    // Headphones (react to mid frequencies)
    float leftEar = length(uv - vec2(-0.5, 0.2)) - 0.1 + medFreq * 0.05 * sin(iTime * 3.0);
    float rightEar = length(uv - vec2(0.5, 0.2)) - 0.1 + medFreq * 0.05 * sin(iTime * 3.0);
    color = mix(color, vec3(1.0, 1.0, 1.0), smoothstep(0.02, 0.0, leftEar));
    color = mix(color, vec3(1.0, 1.0, 1.0), smoothstep(0.02, 0.0, rightEar));

    // Text ("MAC") approximation (reacts to treble)
    vec2 macPos = vec2(0.0, -0.4);
    float textSize = 0.05 + topFreq * 0.02 * cos(iTime * 5.0);
    float mac = length(uv - macPos) - textSize; // Simplified block for text
    color = mix(color, vec3(0.0, 0.0, 0.0), smoothstep(0.02, 0.0, mac));

    // Output final color
    fragColor = vec4(color, 1.0);
}
